"""WordprocessingML -> the document model.

The parser resolves the full formatting cascade (document defaults, table
styles, numbering, paragraph and character styles, direct formatting) so the
layout engine works with plain values.
"""
from __future__ import annotations

import re
from dataclasses import replace
from typing import Optional

from ..oxml import package as opc
from .model import (BreakRun, Cell, Document, FieldRun, FloatingObject,
                    HeaderFooter, ImageRun, Link, NoteRun, NumberLabel,
                    Paragraph, Row, Section, ShapeRun, TabRun, Table, TextRun)
from .numbering import Numbering
from ..oxml import (emu, find, findall, get, int_of, local, on_off, qn, twips,
                    val)
from .props import (CellProps, ParaProps, RunProps, parse_borders, parse_ppr,
                    parse_rpr, parse_tblpr, parse_tcpr, parse_trpr)
from .styles import StyleSheet, Theme

DYNAMIC_FIELDS = {'PAGE', 'NUMPAGES', 'SECTIONPAGES', 'DATE', 'TIME', 'FILENAME',
                  'SECTION', 'PRINTDATE', 'SAVEDATE', 'CREATEDATE'}

# Conditional table formatting, in the order Word applies it.
COND_ORDER = ['wholeTable', 'band1Vert', 'band2Vert', 'band1Horz', 'band2Horz',
              'firstCol', 'lastCol', 'firstRow', 'lastRow',
              'nwCell', 'neCell', 'swCell', 'seCell']


class CellContext:
    """Formatting a table (and its style) imposes on the cells inside it."""

    __slots__ = ('ppr', 'rpr', 'nesting')

    def __init__(self, ppr=None, rpr=None, nesting=0):
        self.ppr = ppr or ParaProps()
        self.rpr = rpr or RunProps()
        self.nesting = nesting


class Parser:
    def __init__(self, package, options=None):
        self.pkg = package
        self.options = options or {}
        self.main = package.main_part
        _, theme_root = package.part_by_type(opc.RT_THEME)
        self.theme = Theme(theme_root)
        _, styles_root = package.part_by_type(opc.RT_STYLES)
        self.styles = StyleSheet(styles_root, self.theme)
        _, numbering_root = package.part_by_type(opc.RT_NUMBERING)
        self.numbering = Numbering(numbering_root, self.styles)
        self.settings = self._parse_settings()
        self.warnings: list = []
        self._bookmarks: list = []

    # -- entry point --------------------------------------------------------
    def parse(self) -> Document:
        root = self.pkg.xml(self.main)
        body = find(root, 'w:body')
        doc = Document(styles=self.styles, numbering=self.numbering,
                       theme=self.theme, package=self.pkg, settings=self.settings)
        if body is None:
            doc.sections.append(Section())
            return doc

        sections = []
        pending: list = []
        for child in body:
            tag = local(child.tag)
            if tag == 'p':
                sect_el = find(child, 'w:pPr/w:sectPr')
                para = self._paragraph(child, self.main)
                if para is not None:
                    pending.append(para)
                if sect_el is not None:
                    section = self._section(sect_el,
                                            sections[-1] if sections else None)
                    section.blocks = pending
                    sections.append(section)
                    pending = []
            elif tag == 'tbl':
                table = self._table(child, self.main)
                if table is not None:
                    pending.append(table)
            elif tag == 'sectPr':
                section = self._section(child, sections[-1] if sections else None)
                section.blocks = pending
                sections.append(section)
                pending = []
            elif tag in ('sdt', 'customXml'):
                pending.extend(self._blocks(self._sdt_content(child), self.main))
            elif tag == 'AlternateContent':
                chosen = self._alternate(child)
                if chosen is not None:
                    pending.extend(self._blocks(chosen, self.main))
        if pending:
            if sections and not sections[-1].blocks:
                sections[-1].blocks = pending
            else:
                trailing = (replace_section(sections[-1]) if sections
                            else self._section(None))
                trailing.blocks = pending
                sections.append(trailing)
        if not sections:
            sections.append(self._section(None))
        doc.sections = sections
        self._load_notes(doc)
        doc.properties = self._core_properties()
        return doc

    # -- settings / metadata ------------------------------------------------
    def _parse_settings(self) -> dict:
        _, root = self.pkg.part_by_type(opc.RT_SETTINGS)
        out = {'default_tab': 36.0, 'even_odd_headers': False, 'mirror_margins': False,
               'footnote_num_fmt': 'decimal', 'endnote_num_fmt': 'lowerRoman',
               'footnote_restart': 'continuous', 'compat': {},
               'compat_mode': 12}
        if root is None:
            return out
        tab = find(root, 'w:defaultTabStop')
        if tab is not None:
            out['default_tab'] = twips(val(tab), 36.0)
        out['even_odd_headers'] = bool(on_off(find(root, 'w:evenAndOddHeaders')))
        out['mirror_margins'] = bool(on_off(find(root, 'w:mirrorMargins')))
        fn = find(root, 'w:footnotePr')
        if fn is not None:
            out['footnote_num_fmt'] = val(find(fn, 'w:numFmt'), 'decimal') or 'decimal'
            out['footnote_restart'] = val(find(fn, 'w:numRestart'), 'continuous') or 'continuous'
        en = find(root, 'w:endnotePr')
        if en is not None:
            out['endnote_num_fmt'] = val(find(en, 'w:numFmt'), 'lowerRoman') or 'lowerRoman'
        compat = find(root, 'w:compat')
        if compat is not None:
            for child in compat:
                if local(child.tag) == 'compatSetting':
                    # Word 2013 and later changed a few layout rules; which
                    # ones apply is decided by this mode, not by the version
                    # that wrote the file.
                    if get(child, 'w:name') == 'compatibilityMode':
                        out['compat_mode'] = int_of(get(child, 'w:val'), 12)
                    continue
                out['compat'][local(child.tag)] = val(child, '1')
        return out

    def _core_properties(self) -> dict:
        out = {}
        name = self.pkg.related_by_type(
            '/', 'http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties')
        root = self.pkg.xml(name) if name else None
        if root is not None:
            for child in root:
                key = local(child.tag)
                if child.text:
                    out[key] = child.text
        return out

    def _load_notes(self, doc: Document):
        for rel, attr, container in ((opc.RT_FOOTNOTES, 'footnotes', 'footnote'),
                                     (opc.RT_ENDNOTES, 'endnotes', 'endnote')):
            part, root = self.pkg.part_by_type(rel)
            if root is None:
                continue
            store = {}
            for el in findall(root, 'w:' + container):
                note_type = get(el, 'w:type')
                if note_type in ('separator', 'continuationSeparator', 'continuationNotice'):
                    continue
                note_id = get(el, 'w:id')
                store[note_id] = self._blocks(el, part)
            setattr(doc, attr, store)

    # -- structure ----------------------------------------------------------
    def _blocks(self, container, part, ctx: Optional[CellContext] = None) -> list:
        out = []
        if container is None:
            return out
        for child in container:
            tag = local(child.tag)
            if tag == 'p':
                para = self._paragraph(child, part, ctx)
                if para is not None:
                    out.append(para)
            elif tag == 'tbl':
                table = self._table(child, part, ctx)
                if table is not None:
                    out.append(table)
            elif tag in ('sdt', 'customXml'):
                out.extend(self._blocks(self._sdt_content(child), part, ctx))
            elif tag == 'AlternateContent':
                chosen = self._alternate(child)
                if chosen is not None:
                    out.extend(self._blocks(chosen, part, ctx))
        return out

    @staticmethod
    def _sdt_content(el):
        content = find(el, 'w:sdtContent')
        return content if content is not None else el

    @staticmethod
    def _alternate(el):
        fallback = el.find(qn('mc:Fallback'))
        choice = el.find(qn('mc:Choice'))
        # The fallback is VML, which we understand better than DrawingML shapes.
        if fallback is not None and len(fallback):
            return fallback
        return choice

    def _section(self, el, previous: Optional[Section] = None) -> Section:
        section = Section()
        if el is None:
            return section
        pg_sz = find(el, 'w:pgSz')
        if pg_sz is not None:
            section.width = twips(get(pg_sz, 'w:w'), 612.0)
            section.height = twips(get(pg_sz, 'w:h'), 792.0)
            section.landscape = get(pg_sz, 'w:orient') == 'landscape'
        pg_mar = find(el, 'w:pgMar')
        if pg_mar is not None:
            section.margin_top = twips(get(pg_mar, 'w:top'), 72.0)
            section.margin_bottom = twips(get(pg_mar, 'w:bottom'), 72.0)
            section.margin_left = twips(get(pg_mar, 'w:left'), 72.0)
            section.margin_right = twips(get(pg_mar, 'w:right'), 72.0)
            section.header_distance = twips(get(pg_mar, 'w:header'), 36.0)
            section.footer_distance = twips(get(pg_mar, 'w:footer'), 36.0)
            section.gutter = twips(get(pg_mar, 'w:gutter'), 0.0)
        cols = find(el, 'w:cols')
        if cols is not None:
            section.columns = max(1, int_of(get(cols, 'w:num'), 1))
            section.column_space = twips(get(cols, 'w:space'), 36.0)
            section.column_separator = get(cols, 'w:sep') in ('1', 'true', 'on')
            equal = get(cols, 'w:equalWidth')
            col_els = findall(cols, 'w:col')
            if equal in ('0', 'false') and col_els:
                widths = []
                for c in col_els:
                    widths.append((twips(get(c, 'w:w'), 0.0),
                                   twips(get(c, 'w:space'), 0.0)))
                section.column_widths = widths
                section.columns = len(widths)
        section.title_page = bool(on_off(find(el, 'w:titlePg')))
        pg_num = find(el, 'w:pgNumType')
        if pg_num is not None:
            section.page_num_start = int_of(get(pg_num, 'w:start'))
            section.page_num_format = get(pg_num, 'w:fmt')
        section.vertical_align = val(find(el, 'w:vAlign'), 'top') or 'top'
        section.break_type = val(find(el, 'w:type'), 'nextPage') or 'nextPage'
        section.borders = parse_borders(find(el, 'w:pgBorders'))
        for ref in findall(el, 'w:headerReference'):
            self._load_header_footer(section.headers, ref)
        for ref in findall(el, 'w:footerReference'):
            self._load_header_footer(section.footers, ref)
        if previous is not None:
            # A section that names no header or footer of a given kind keeps
            # the one before it - what Word calls "link to previous", and what
            # every document with a landscape annex relies on.
            for kind, hf in previous.headers.items():
                section.headers.setdefault(kind, hf)
            for kind, hf in previous.footers.items():
                section.footers.setdefault(kind, hf)
        return section

    def _load_header_footer(self, store, ref):
        rid = get(ref, 'r:id')
        kind = get(ref, 'w:type', 'default') or 'default'
        if not rid:
            return
        part = self.pkg.related(self.main, rid)
        if not part:
            return
        root = self.pkg.xml(part)
        if root is None:
            return
        body = find(root, 'w:hdr') if local(root.tag) not in ('hdr', 'ftr') else root
        # Headers must not disturb the body's list counters.
        saved = {k: list(v) for k, v in self.numbering._counters.items()}
        try:
            blocks = self._blocks(body if body is not None else root, part)
        finally:
            self.numbering._counters = saved
        store[kind] = HeaderFooter(blocks=blocks, part=part)

    # -- paragraphs ---------------------------------------------------------
    def _paragraph(self, el, part, ctx: Optional[CellContext] = None) -> Optional[Paragraph]:
        ppr_el = find(el, 'w:pPr')
        direct = parse_ppr(ppr_el)
        style_id = direct.style_id or self.styles.default_para_style
        style_ppr = self.styles.style_only_ppr(style_id)

        num_id = direct.num_id
        num_level = direct.num_level
        if num_id is None:
            num_id = style_ppr.num_id
            if num_level is None:
                num_level = style_ppr.num_level
            if num_id is None and style_id:
                num_id, num_level = self._style_numbering(style_id, num_level)
        if num_level is None:
            num_level = self._style_level(style_id) or 0

        level = self.numbering.level(num_id, num_level) if num_id else None
        lvl_ppr = level.ppr if level is not None else ParaProps()

        props = self.styles.doc_ppr
        if ctx is not None:
            props = props.merge(ctx.ppr)
        props = props.merge(style_ppr).merge(lvl_ppr).merge(direct)
        props = replace(props, style_id=style_id, num_id=num_id, num_level=num_level)

        base_rpr = self.styles.doc_rpr
        if ctx is not None:
            base_rpr = base_rpr.merge(ctx.rpr)
        base_rpr = base_rpr.merge(self.styles.style_only_rpr(style_id))
        base_rpr = self._resolve_theme_fonts(base_rpr)
        if not base_rpr.font_ascii:
            base_rpr = replace(base_rpr, font_ascii=self.theme.minor_font)

        mark_props = self._run_props(find(ppr_el, 'w:rPr'), base_rpr)

        para = Paragraph(props=props, mark_props=mark_props, style_id=style_id,
                         in_table=bool(ctx))
        para.items = self._inlines(el, part, base_rpr, para)

        if num_id and level is not None and not self._numbering_suppressed(props, para):
            text, lvl = self.numbering.next_label(num_id, num_level)
            if text is not None:
                label_props = base_rpr.merge(lvl.rpr) if lvl is not None else base_rpr
                label_props = self._resolve_theme_fonts(label_props)
                if lvl is not None and lvl.num_fmt == 'bullet' and text != lvl.lvl_text:
                    # the glyph was mapped out of a Symbol/Wingdings code point,
                    # so the symbol font no longer applies to it
                    label_props = replace(label_props, font_ascii=None,
                                          font_hansi=None, font_eastasia=None)
                if para.items:
                    first = next((i for i in para.items if isinstance(i, TextRun)), None)
                    if first is not None:
                        label_props = _inherit_label_size(label_props, first.props)
                para.number = NumberLabel(text=text, props=label_props,
                                          suffix=(lvl.suffix if lvl else 'tab'),
                                          align=(lvl.jc if lvl else 'left'),
                                          font_family=label_props.font_ascii)
        return para

    def _style_numbering(self, style_id, num_level):
        """Numbering pulled in through a style's numPr or a numbering style."""
        for style in reversed(self.styles.chain(style_id)):
            if style.ppr.num_id:
                return style.ppr.num_id, (num_level if num_level is not None
                                          else style.ppr.num_level)
        return None, num_level

    def _style_level(self, style_id) -> Optional[int]:
        for style in reversed(self.styles.chain(style_id)):
            if style.ppr.num_level is not None:
                return style.ppr.num_level
        return None

    @staticmethod
    def _numbering_suppressed(props, para) -> bool:
        return props.num_id == 0

    def _resolve_theme_fonts(self, props: RunProps) -> RunProps:
        if props.theme_ascii and not props.font_ascii:
            resolved = self.theme.font(props.theme_ascii)
            if resolved:
                props = replace(props, font_ascii=resolved)
        if props.theme_hansi and not props.font_hansi:
            resolved = self.theme.font(props.theme_hansi)
            if resolved:
                props = replace(props, font_hansi=resolved)
        return props

    def _run_props(self, rpr_el, base: RunProps) -> RunProps:
        direct = parse_rpr(rpr_el, self.theme)
        props = base
        if direct.style_id:
            props = self.styles.char_props(direct.style_id, props)
        props = props.merge(direct)
        return self._resolve_theme_fonts(props)

    # -- inline content -----------------------------------------------------
    def _inlines(self, para_el, part, base_rpr, para) -> list:
        items: list = []
        state = {'fields': [], 'link': None}
        self._walk_inline(para_el, part, base_rpr, items, state, para)
        return items

    def _walk_inline(self, container, part, base_rpr, items, state, para,
                     link: Optional[Link] = None):
        for child in container:
            tag = local(child.tag)
            if tag == 'r':
                self._run(child, part, base_rpr, items, state, link, para)
            elif tag == 'hyperlink':
                items_link = self._hyperlink(child, part)
                self._walk_inline(child, part, base_rpr, items, state, para,
                                  items_link or link)
            elif tag in ('ins', 'smartTag', 'bdo', 'dir'):
                self._walk_inline(child, part, base_rpr, items, state, para, link)
            elif tag == 'del':
                continue
            elif tag in ('sdt', 'customXml'):
                self._walk_inline(self._sdt_content(child), part, base_rpr, items,
                                  state, para, link)
            elif tag == 'AlternateContent':
                chosen = self._alternate(child)
                if chosen is not None:
                    self._walk_inline(chosen, part, base_rpr, items, state, para, link)
            elif tag == 'fldSimple':
                self._simple_field(child, part, base_rpr, items, state, para, link)
            elif tag == 'bookmarkStart':
                name = get(child, 'w:name')
                if name and name != '_GoBack':
                    para.bookmarks.append(name)
            elif tag == 'subDoc':
                continue

    def _hyperlink(self, el, part) -> Optional[Link]:
        rid = get(el, 'r:id')
        anchor = get(el, 'w:anchor')
        tooltip = get(el, 'w:tooltip')
        url = None
        if rid:
            target = self.pkg.related(part, rid)
            if target:
                url = target
        if url and anchor:
            url = '%s#%s' % (url, anchor)
        if not url and not anchor:
            return None
        return Link(url=url, anchor=anchor if not url else None, tooltip=tooltip)

    def _simple_field(self, el, part, base_rpr, items, state, para, link):
        instr = get(el, 'w:instr', '') or ''
        kind, argument, fmt = parse_field(instr)
        cached: list = []
        self._walk_inline(el, part, base_rpr, cached, state, para, link)
        if kind in DYNAMIC_FIELDS:
            props = cached[0].props if cached else base_rpr
            text = ''.join(i.text for i in cached if isinstance(i, TextRun))
            items.append(FieldRun(props=props, link=link, kind=kind, text=text,
                                  argument=argument, fmt=fmt))
        else:
            items.extend(cached)

    def _run(self, el, part, base_rpr, items, state, link, para=None):
        props = self._run_props(find(el, 'w:rPr'), base_rpr)
        if props.vanish and not self.options.get('show_hidden'):
            return
        field = state['fields'][-1] if state['fields'] else None
        for child in el:
            tag = local(child.tag)
            if tag == 'fldChar':
                kind = get(child, 'w:fldCharType')
                if kind == 'begin':
                    state['fields'].append({'instr': '', 'in_result': False,
                                            'items': [], 'props': props})
                elif kind == 'separate':
                    if state['fields']:
                        state['fields'][-1]['in_result'] = True
                elif kind == 'end' and state['fields']:
                    done = state['fields'].pop()
                    target = (state['fields'][-1]['items']
                              if state['fields'] else items)
                    self._finish_field(done, target, link)
                field = state['fields'][-1] if state['fields'] else None
                continue
            if tag == 'instrText':
                if field is not None and not field['in_result']:
                    field['instr'] += child.text or ''
                continue
            sink = field['items'] if field is not None else items
            if tag == 't':
                text = child.text or ''
                if text:
                    sink.append(TextRun(props=props, link=link, text=text))
            elif tag == 'delText':
                continue
            elif tag == 'tab':
                sink.append(TabRun(props=props, link=link))
            elif tag == 'br':
                kind = get(child, 'w:type', 'textWrapping') or 'textWrapping'
                mapped = {'page': 'page', 'column': 'column'}.get(kind, 'line')
                sink.append(BreakRun(props=props, link=link, kind=mapped,
                                     clear=get(child, 'w:clear')))
            elif tag == 'cr':
                sink.append(BreakRun(props=props, link=link, kind='line'))
            elif tag == 'noBreakHyphen':
                sink.append(TextRun(props=props, link=link, text='‑'))
            elif tag == 'softHyphen':
                continue
            elif tag == 'sym':
                char = get(child, 'w:char')
                font = get(child, 'w:font')
                if char:
                    try:
                        code = int(char, 16)
                    except ValueError:
                        code = None
                    if code is not None:
                        sym_props = replace(props, font_ascii=font or props.font_ascii,
                                            font_hansi=font or props.font_hansi)
                        sink.append(TextRun(props=sym_props, link=link, text=chr(code)))
            elif tag == 'drawing':
                self._drawing(child, part, props, sink, link, para)
            elif tag == 'pict':
                self._vml_picture(child, part, props, sink, link, para)
            elif tag == 'object':
                if find(child, 'v:shape') is not None:
                    self._vml_picture(child, part, props, sink, link, para)
            elif tag in ('footnoteReference', 'endnoteReference'):
                sink.append(NoteRun(props=props, link=link,
                                    note_id=get(child, 'w:id', ''),
                                    kind='footnote' if tag.startswith('foot') else 'endnote'))
            elif tag in ('footnoteRef', 'endnoteRef'):
                sink.append(FieldRun(props=props, link=link, kind='NOTEREF'))
            elif tag == 'ptab':
                sink.append(TabRun(props=props, link=link))

    def _finish_field(self, field, target, link):
        kind, argument, fmt = parse_field(field['instr'])
        cached_items = field['items']
        if kind == 'HYPERLINK' and argument:
            url = argument.strip('"')
            field_link = Link(url=url if '://' in url or url.startswith('mailto:') else None,
                              anchor=None if '://' in url else url)
            for item in cached_items:
                if item.link is None:
                    item.link = field_link
            target.extend(cached_items)
            return
        if kind in DYNAMIC_FIELDS:
            props = cached_items[0].props if cached_items else field['props']
            text = ''.join(i.text for i in cached_items if isinstance(i, TextRun))
            target.append(FieldRun(props=props, link=link, kind=kind, text=text,
                                   argument=argument, fmt=fmt))
            return
        target.extend(cached_items)

    # -- drawings -----------------------------------------------------------
    def _drawing(self, el, part, props, sink, link, para=None):
        for node in el:
            tag = local(node.tag)
            if tag not in ('inline', 'anchor'):
                continue
            extent = find(node, 'wp:extent')
            width = height = 0.0
            if extent is not None:
                width = emu(extent.get('cx'), 0.0)
                height = emu(extent.get('cy'), 0.0)
            doc_pr = find(node, 'wp:docPr')
            alt = (doc_pr.get('descr') or doc_pr.get('name') or '') if doc_pr is not None else ''
            graphic_data = find(node, 'a:graphic/a:graphicData')
            if graphic_data is None:
                continue
            floating = tag == 'anchor' and para is not None
            target = [] if floating else sink
            handled = False
            pic = find(graphic_data, 'pic:pic')
            if pic is not None:
                handled = self._emit_picture(pic, part, props, target, link,
                                             width, height, alt)
            blocks = None
            if not handled:
                txbx = graphic_data.find('.//' + qn('w:txbxContent'))
                if txbx is not None:
                    blocks = self._blocks(txbx, part)
                    if not floating:
                        sink.append(ShapeRun(props=props, link=link, width=width,
                                             height=height, blocks=blocks))
                    handled = True
            if not handled:
                if alt:
                    self.warnings.append('unsupported drawing: %s' % alt)
                continue
            if floating:
                image = target[0] if target and isinstance(target[0], ImageRun) else None
                para.floats.append(self._anchor(node, image, blocks, width, height,
                                                alt))

    def _anchor(self, node, image, blocks, width, height, alt) -> FloatingObject:
        pos_h = find(node, 'wp:positionH')
        pos_v = find(node, 'wp:positionV')
        wrap = 'none'
        for name in ('wrapSquare', 'wrapTight', 'wrapThrough', 'wrapTopAndBottom',
                     'wrapNone'):
            if find(node, 'wp:' + name) is not None:
                wrap = name[4:].lower()
                break
        obj = FloatingObject(
            image=image, blocks=blocks or [], width=width, height=height,
            h_relative=(get(pos_h, 'relativeFrom', 'column') if pos_h is not None
                        else 'column'),
            v_relative=(get(pos_v, 'relativeFrom', 'paragraph') if pos_v is not None
                        else 'paragraph'),
            h_offset=emu(_text_of(find(pos_h, 'wp:posOffset')), 0.0) or 0.0,
            v_offset=emu(_text_of(find(pos_v, 'wp:posOffset')), 0.0) or 0.0,
            h_align=_text_of(find(pos_h, 'wp:align')),
            v_align=_text_of(find(pos_v, 'wp:align')),
            behind=get(node, 'behindDoc') in ('1', 'true'),
            wrap=wrap,
            z_index=int_of(get(node, 'relativeHeight'), 0),
            rotation=(image.rotation if image is not None else 0.0),
            alt=alt)
        return obj

    def _emit_picture(self, pic, part, props, sink, link, width, height, alt) -> bool:
        blip = find(pic, 'pic:blipFill/a:blip')
        if blip is None:
            return False
        rid = get(blip, 'r:embed') or get(blip, 'r:link')
        if not rid:
            return False
        data = self.pkg.image_bytes(part, rid)
        if not data:
            return False
        crop = None
        src_rect = find(pic, 'pic:blipFill/a:srcRect')
        if src_rect is not None:
            crop = tuple(int_of(src_rect.get(side), 0) / 100000.0
                         for side in ('l', 't', 'r', 'b'))
            if not any(crop):
                crop = None
        rotation = 0.0
        xfrm = find(pic, 'pic:spPr/a:xfrm')
        if xfrm is not None:
            rotation = int_of(xfrm.get('rot'), 0) / 60000.0
        name = self.pkg.related(part, rid) or ''
        fmt = name.rsplit('.', 1)[-1].lower() if '.' in name else ''
        sink.append(ImageRun(props=props, link=link, data=data, width=width,
                             height=height, alt=alt, rotation=rotation, fmt=fmt,
                             crop=crop))
        return True

    def _vml_picture(self, el, part, props, sink, link, para=None):
        for shape in el.iter():
            tag = local(shape.tag)
            if tag not in ('shape', 'rect', 'roundrect', 'oval'):
                continue
            style = _vml_style(shape.get('style') or '')
            width, height = _vml_size(style)
            floating = para is not None and style.get('position') == 'absolute'
            image_el = shape.find(qn('v:imagedata'))
            image = None
            if image_el is not None:
                rid = image_el.get(qn('r:id')) or image_el.get(qn('o:relid'))
                data = self.pkg.image_bytes(part, rid) if rid else None
                if data:
                    name = self.pkg.related(part, rid) or ''
                    fmt = name.rsplit('.', 1)[-1].lower() if '.' in name else ''
                    image = ImageRun(props=props, link=link, data=data,
                                     width=width or 0.0, height=height or 0.0,
                                     alt=image_el.get('title') or '', fmt=fmt)
            blocks = None
            txbx = shape.find('.//' + qn('w:txbxContent'))
            if txbx is not None:
                blocks = self._blocks(txbx, part)
            if image is None and blocks is None:
                continue
            if floating:
                para.floats.append(self._vml_anchor(shape, style, image, blocks,
                                                    width or 0.0, height or 0.0))
            elif image is not None:
                sink.append(image)
            else:
                sink.append(ShapeRun(props=props, link=link, width=width or 0.0,
                                     height=height or 0.0, blocks=blocks))
            return

    def _vml_anchor(self, shape, style, image, blocks, width, height):
        rel_map = {'page': 'page', 'margin': 'margin', 'text': 'paragraph',
                   'line': 'line', 'column': 'column', 'char': 'character'}
        z = int_of(style.get('z-index'), 0) or 0
        return FloatingObject(
            image=image, blocks=blocks or [], width=width, height=height,
            h_relative=rel_map.get(
                style.get('mso-position-horizontal-relative', 'column'), 'column'),
            v_relative=rel_map.get(
                style.get('mso-position-vertical-relative', 'paragraph'), 'paragraph'),
            h_offset=_css_length(style.get('margin-left', '0')) or 0.0,
            v_offset=_css_length(style.get('margin-top', '0')) or 0.0,
            h_align=style.get('mso-position-horizontal'),
            v_align=style.get('mso-position-vertical'),
            behind=z < 0, z_index=z,
            fill=(shape.get('fillcolor') or None),
            stroke=(shape.get('strokecolor') or None),
            alt=shape.get('alt') or '')

    # -- tables -------------------------------------------------------------
    def _table(self, el, part, ctx: Optional[CellContext] = None) -> Optional[Table]:
        tbl_pr = find(el, 'w:tblPr')
        direct = parse_tblpr(tbl_pr)
        style_id = direct.style_id
        style_tbl, style_row, style_cell, style_ppr, style_rpr = \
            self.styles.table_props(style_id)
        props = style_tbl.merge(direct)
        look = props.look or {}

        grid = []
        for col in findall(el, 'w:tblGrid/w:gridCol'):
            grid.append(twips(get(col, 'w:w'), 0.0))

        rows_el = [child for child in el if local(child.tag) == 'tr']
        table = Table(grid=grid, props=props, style_id=style_id, look=look,
                      nesting=(ctx.nesting if ctx else 0))

        row_band = props.row_band_size or 1
        col_band = props.col_band_size or 1
        header_rows = 0
        for row_el in rows_el:
            if on_off(find(row_el, 'w:trPr/w:tblHeader')):
                header_rows += 1
            else:
                break

        for row_index, row_el in enumerate(rows_el):
            row_props = style_row.merge(parse_trpr(find(row_el, 'w:trPr')))
            row = Row(props=row_props, header=bool(row_props.header))
            column = 0
            cell_els = [c for c in row_el if local(c.tag) == 'tc']
            for cell_index, cell_el in enumerate(cell_els):
                cell_direct = parse_tcpr(find(cell_el, 'w:tcPr'))
                span = max(1, cell_direct.grid_span or 1)
                conds = self._conditions(row_index, len(rows_el), column,
                                         len(grid) or len(cell_els), span,
                                         header_rows, row_band, col_band, look)
                cond_cell, cond_ppr, cond_rpr = self._conditional_props(style_id, conds)
                cell_props = style_cell.merge(cond_cell).merge(cell_direct)
                cell_props = replace(cell_props, borders=self._cell_borders(
                    props, style_id, conds, cell_direct, row_index, len(rows_el),
                    column, len(grid) or len(cell_els), span,
                    header_rows, row_band))
                cell_ctx = CellContext(
                    ppr=style_ppr.merge(cond_ppr),
                    rpr=style_rpr.merge(cond_rpr),
                    nesting=(ctx.nesting + 1 if ctx else 1))
                cell = Cell(props=cell_props, grid_span=span,
                            v_merge=cell_direct.v_merge, column=column,
                            width=cell_direct.width)
                cell.blocks = self._blocks(cell_el, part, cell_ctx)
                # A cell cannot end with a table, so Word requires an empty
                # paragraph after one - and then gives it no height.
                while (len(cell.blocks) >= 2
                       and isinstance(cell.blocks[-1], Paragraph)
                       and not cell.blocks[-1].items
                       and not cell.blocks[-1].floats
                       and isinstance(cell.blocks[-2], Table)):
                    cell.blocks.pop()
                if not cell.blocks:
                    cell.blocks = [Paragraph(props=ParaProps(), in_table=True,
                                             mark_props=self.styles.doc_rpr)]
                row.cells.append(cell)
                column += span
            if row.cells:
                table.rows.append(row)
        if not table.rows:
            return None
        return table

    @staticmethod
    def _conditions(row_index, row_count, column, col_count, span, header_rows,
                    row_band, col_band, look) -> list:
        conds = ['wholeTable']
        first_row = look.get('firstRow', True)
        last_row = look.get('lastRow', False)
        first_col = look.get('firstColumn', True)
        last_col = look.get('lastColumn', False)
        no_hband = look.get('noHBand', False)
        no_vband = look.get('noVBand', False)
        body_index = row_index - header_rows
        if not no_vband and col_band:
            band = (column // max(1, col_band)) % 2
            conds.append('band1Vert' if band == 0 else 'band2Vert')
        if not no_hband and row_band and body_index >= 0:
            band = (body_index // max(1, row_band)) % 2
            conds.append('band1Horz' if band == 0 else 'band2Horz')
        if first_col and column == 0:
            conds.append('firstCol')
        if last_col and column + span >= col_count:
            conds.append('lastCol')
        if first_row and row_index == 0:
            conds.append('firstRow')
        if last_row and row_index == row_count - 1:
            conds.append('lastRow')
        if first_row and row_index == 0 and column == 0:
            conds.append('nwCell')
        if first_row and row_index == 0 and column + span >= col_count:
            conds.append('neCell')
        if last_row and row_index == row_count - 1 and column == 0:
            conds.append('swCell')
        if last_row and row_index == row_count - 1 and column + span >= col_count:
            conds.append('seCell')
        return [c for c in COND_ORDER if c in conds]

    def _conditional_props(self, style_id, conds):
        cell = CellProps()
        ppr = ParaProps()
        rpr = RunProps()
        for cond in conds:
            resolved = self.styles.table_conditional(style_id, cond)
            if resolved is None:
                continue
            _tbl, _row, cond_cell, cond_ppr, cond_rpr = resolved
            cell = cell.merge(cond_cell)
            ppr = ppr.merge(cond_ppr)
            rpr = rpr.merge(cond_rpr)
        return cell, ppr, rpr

    def _cell_borders(self, tbl_props, style_id, conds, cell_direct, row_index,
                      row_count, column, col_count, span, header_rows=0,
                      row_band=1):
        """Effective borders for one cell, table borders included."""
        first_row = row_index == 0
        last_row = row_index == row_count - 1
        first_col = column == 0
        last_col = column + span >= col_count
        body_index = row_index - header_rows
        band = max(1, row_band)
        band_top = body_index < 0 or body_index % band == 0
        band_bottom = body_index < 0 or body_index % band == band - 1

        table_borders = dict(tbl_props.borders or {})
        cell_borders = {}
        for cond in conds:
            resolved = self.styles.table_conditional(style_id, cond)
            if resolved is None:
                continue
            cond_tbl, cond_cell = resolved[0], resolved[2]
            if cond_tbl.borders:
                table_borders.update(cond_tbl.borders)
            # Conditional formatting describes a region (a row band, a column,
            # the whole table); its cell borders draw that region's outline,
            # not the edges between cells inside it.
            for side, border in (cond_cell.borders or {}).items():
                if _region_edge(cond, side, first_row, last_row, first_col,
                                last_col, band_top, band_bottom):
                    cell_borders[side] = border
        out = {}
        mapping = {
            'top': table_borders.get('top') if first_row else table_borders.get('insideH'),
            'bottom': table_borders.get('bottom') if last_row else table_borders.get('insideH'),
            'left': table_borders.get('left') if first_col else table_borders.get('insideV'),
            'right': table_borders.get('right') if last_col else table_borders.get('insideV'),
        }
        for side, border in mapping.items():
            if border is not None:
                out[side] = border
        for side, border in cell_borders.items():
            out[side] = border
        for side, border in (cell_direct.borders or {}).items():
            out[side] = border
        return out or None


HORIZONTAL_REGIONS = ('firstRow', 'lastRow', 'band1Horz', 'band2Horz')
VERTICAL_REGIONS = ('firstCol', 'lastCol', 'band1Vert', 'band2Vert')


def _region_edge(cond, side, first_row, last_row, first_col, last_col,
                 band_top, band_bottom) -> bool:
    """Is this cell edge on the outline of the conditional's region?"""
    if cond in HORIZONTAL_REGIONS:
        if side == 'left':
            return first_col
        if side == 'right':
            return last_col
        if side == 'top':
            return band_top or cond in ('firstRow', 'lastRow')
        if side == 'bottom':
            return band_bottom or cond in ('firstRow', 'lastRow')
        return True
    if cond in VERTICAL_REGIONS:
        if side == 'top':
            return first_row
        if side == 'bottom':
            return last_row
        return True
    if cond == 'wholeTable':
        return {'left': first_col, 'right': last_col,
                'top': first_row, 'bottom': last_row}.get(side, True)
    return True


def _inherit_label_size(label_props: RunProps, first_props: RunProps) -> RunProps:
    """List labels follow the first run's size unless the level overrides it."""
    if label_props.size is None and first_props.size is not None:
        label_props = replace(label_props, size=first_props.size)
    return label_props


def _vml_style(style: str) -> dict:
    out = {}
    for piece in style.split(';'):
        if ':' not in piece:
            continue
        key, _, value = piece.partition(':')
        out[key.strip().lower()] = value.strip()
    return out


def _vml_size(style: dict):
    return _css_length(style.get('width', '')), _css_length(style.get('height', ''))


def _text_of(el):
    if el is None:
        return None
    return (el.text or '').strip() or None


def _css_length(value: str):
    match = re.match(r'^(-?[\d.]+)\s*(pt|px|in|cm|mm|pc|em)?$', value)
    if not match:
        return None
    number = float(match.group(1))
    unit = match.group(2) or 'pt'
    factor = {'pt': 1.0, 'px': 0.75, 'in': 72.0, 'cm': 28.3465, 'mm': 2.83465,
              'pc': 12.0, 'em': 12.0}.get(unit, 1.0)
    return number * factor


FIELD_RE = re.compile(r'^\s*([A-Za-z]+)\s*(.*)$', re.S)


def parse_field(instr: str):
    """``' PAGE  \\* MERGEFORMAT '`` -> ``('PAGE', '', 'MERGEFORMAT')``."""
    instr = (instr or '').strip()
    match = FIELD_RE.match(instr)
    if not match:
        return '', '', ''
    kind = match.group(1).upper()
    rest = match.group(2).strip()
    fmt = ''
    switch = rest.find('\\')
    if switch >= 0:
        fmt = rest[switch:].strip()
        rest = rest[:switch].strip()
    return kind, rest, fmt


def replace_section(section: Section) -> Section:
    """A copy of *section* with no content, for trailing body content."""
    clone = Section(**{k: v for k, v in section.__dict__.items()
                       if k not in ('blocks',)})
    clone.blocks = []
    return clone


def parse_document(source, options=None) -> Document:
    package = source if isinstance(source, opc.Package) else opc.Package(source)
    parser = Parser(package, options)
    doc = parser.parse()
    doc.warnings = parser.warnings
    return doc
